package com.wissenup.domain.communication.repository; import com.wissenup.domain.communication.entity.CalendarEvent; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.time.LocalDate; import java.util.*;
public interface CalendarEventRepository extends JpaRepository<CalendarEvent,Long>{Optional<CalendarEvent> findByCalendarIdAndOrganizationId(Long id,Long org);List<CalendarEvent> findAllByOrganizationIdOrderByStartDateAsc(Long org);@Query("select count(e)>0 from CalendarEvent e where e.organizationId=:org and e.status='ACTIVE' and e.isHoliday=true and e.startDate<=:date and (e.endDate is null or e.endDate>=:date)") boolean isHoliday(@Param("org")Long org,@Param("date")LocalDate date);}
